1	package org.springframework.samples.petclinic.model;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	
8	/**
9	 * Builds an owner's customerCode as {@code <REGION>-<HASH8>}: REGION is the region
10	 * derived from the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, otherwise
11	 * "UNKNOWN") and HASH8 is the first 8 upper-case hex characters of
12	 * SHA-256(normalizedTelephone + lastName).
13	 */
14	public final class CustomerCode {
15	
16	    private CustomerCode() {
17	    }
18	
19	    /** Region-and-hash customerCode for {@code owner}. */
20	    public static String of(Owner owner) {
21	        String region = "UNKNOWN";
22	        String postcode = owner.getPostcode();
23	        if (postcode != null && postcode.matches("\\d{4}")) {
24	            region = switch (Integer.parseInt(postcode) / 100) {
25	                case 20 -> "NSW";
26	                case 30 -> "VIC";
27	                case 40 -> "QLD";
28	                default -> "UNKNOWN";
29	            };
30	        }
31	        byte[] digest;
32	        try {
33	            digest = MessageDigest.getInstance("SHA-256")
34	                .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
35	        } catch (NoSuchAlgorithmException ex) {
36	            throw new IllegalStateException(ex);
37	        }
38	        String hash8 = HexFormat.of().withUpperCase().formatHex(digest).substring(0, 8);
39	        return region + "-" + hash8;
40	    }
41	}
