3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Fiscal-year helper. The fiscal year runs from 1 July to 30 June and is
8	 * identified by the calendar year in which it starts.
9	 */
10	public final class FiscalYear {
11	
12	    private FiscalYear() {
13	    }
14	
15	    /** Calendar year of the fiscal year that contains {@code date}. */
16	    public static int startYearOf(LocalDate date) {
17	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
18	    }
19	
20	    /** The fiscal year of {@code date} formatted as {@code FY<YY>}. */
21	    public static String labelOf(LocalDate date) {
22	        return String.format("FY%02d", startYearOf(date) % 100);
23	    }
24	
25	    /** Whole fiscal years elapsed from {@code date} up to today. */
26	    public static long elapsedSince(LocalDate date) {
27	        return startYearOf(LocalDate.now()) - startYearOf(date);
28	    }
29	}
