1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.MembershipLevels;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives an owner's segment formatted '<TIER>_<AREA>'. TIER is 'PREMIUM' when the
10	 * (capped) membershipLevel is 3 or more, otherwise 'STANDARD'. AREA is 'METRO' when
11	 * the locality is a known region (NSW, VIC or QLD), otherwise 'REGIONAL'.
12	 */
13	final class OwnerSegments {
14	
15	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
16	
17	    private OwnerSegments() {
18	    }
19	
20	    /** The '<TIER>_<AREA>' segment for {@code owner}. */
21	    static String of(Owner owner) {
22	        int level = MembershipLevels.levelOf(owner);
23	        Integer cap = owner.getMembershipLevelCap();
24	        if (cap != null && cap < level) {
25	            level = cap;
26	        }
27	        String tier = level >= 3 ? "PREMIUM" : "STANDARD";
28	        String region = owner.getCustomerCode() == null ? null : owner.getCustomerCode().split("-")[0];
29	        String area = METRO_REGIONS.contains(region) ? "METRO" : "REGIONAL";
30	        return tier + "_" + area;
31	    }
32	}
