1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * Derives an owner's membership points and the level mapped from them. Points:
5	 * +2 for a present email, +1 when namesakeCount is 0, +2 for a household of 3 or
6	 * more and +3 for tenure over one elapsed fiscal year. Level maps points 0-1 to 1, 2-3 to 2,
7	 * 4-5 to 3 and 6 or more to 4.
8	 */
9	public final class MembershipLevels {
10	
11	    private MembershipLevels() {
12	    }
13	
14	    /** Membership points earned by {@code owner}. */
15	    public static int pointsOf(Owner owner) {
16	        int points = 0;
17	        if (owner.getEmail() != null) {
18	            points += 2;
19	        }
20	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
21	            points += 1;
22	        }
23	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
24	            points += 2;
25	        }
26	        java.time.LocalDate registered = owner.getRegistrationDate();
27	        if (registered != null && FiscalYear.elapsedSince(registered) > 1) {
28	            points += 3;
29	        }
30	        return points;
31	    }
32	
33	    /** Membership level (1 to 4) mapped from {@code owner}'s points. */
34	    public static int levelOf(Owner owner) {
35	        return levelOfPoints(pointsOf(owner));
36	    }
37	
38	    /** Maps a points total to its level band. */
39	    public static int levelOfPoints(int points) {
40	        if (points <= 1) {
41	            return 1;
42	        }
43	        if (points <= 3) {
44	            return 2;
45	        }
46	        if (points <= 5) {
47	            return 3;
48	        }
49	        return 4;
50	    }
51	}
