3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import jakarta.persistence.PostPersist;
7	
8	/**
9	 * Emits an audit trail entry to the dedicated {@code AUDIT} logger whenever a new
10	 * {@link Owner} is created, capturing its id, customerCode and registrationDate.
11	 */
12	public class OwnerAuditListener {
13	
14	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
15	
16	    @PostPersist
17	    public void onCreate(Owner owner) {
18	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
19	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
20	            MembershipLevels.levelOf(owner), membershipNumber(owner));
21	        OwnerCreatedEvent.emit(owner);
22	    }
23	
24	    private static String membershipNumber(Owner owner) {
25	        return owner.getCustomerCode() + "-M"
26	            + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
27	    }
28	}
