3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	/**
9	 * Emits the immutable structured {@code OWNER_CREATED} event to the dedicated
10	 * {@code AUDIT} logger, one per created owner, as a JSON object
11	 * {@code {seq, ownerId, customerCode, membershipLevel, event}}. {@code seq} is a
12	 * monotonically increasing integer across creates.
13	 *
14	 * <p>The event carries the owner's current primary identifier via
15	 * {@link #primaryId(Owner)} — the customerCode today; when the customerCode is
16	 * unified into the memberId, only that method changes and the event follows.
17	 */
18	public final class OwnerCreatedEvent {
19	
20	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
21	
22	    private static final AtomicLong SEQ = new AtomicLong();
23	
24	    private OwnerCreatedEvent() {
25	    }
26	
27	    /** Emit the structured create event for {@code owner}. */
28	    public static void emit(Owner owner) {
29	        AUDIT.info(
30	            "{\"seq\":{},\"ownerId\":{},\"customerCode\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
31	            SEQ.incrementAndGet(), owner.getId(), primaryId(owner), MembershipLevels.levelOf(owner));
32	    }
33	
34	    /** The owner's current primary identifier carried by the event. */
35	    private static String primaryId(Owner owner) {
36	        return owner.getCustomerCode();
37	    }
38	}
