@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
@Override
public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
    String idempotencyKey = IdempotencyKeys.current();
    Owner replayed = IdempotencyKeys.seen(idempotencyKey);
    if (replayed != null) {
        return new ResponseEntity<>(ownerMapper.toOwnerDto(replayed), HttpStatus.OK);
    }
    HttpHeaders headers = new HttpHeaders();
    Owner owner = ownerMapper.toOwner(ownerFieldsDto);
    owner.setHouseholdId(Households.idFor(owner));
    Collection<Owner> owners = this.clinicService.findAllOwners().stream()
        .filter(o -> !o.getDeleted()).toList();
    owner.setRegistrationDate(BusinessDays.effective(owner));
    if (owners.stream()
        .filter(o -> owner.getRegistrationDate().equals(o.getRegistrationDate())).count() >= 100) {
        return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
    }
    if (Identities.isDuplicate(owners, owner)) {
        return new ResponseEntity<>(HttpStatus.CONFLICT);
    }
    if (CityCodes.countInCity(owners, owner) >= 50) {
        return new ResponseEntity<>(HttpStatus.CONFLICT);
    }
    owner.setHouseholdMemberCount(Households.size(owners, owner));
    owner.setMembershipLevelCap(Households.ceilingLevel(owners, owner));
    owner.assignCustomerCode(owners);
    owner.setNamesakeCount(Namesakes.count(owners, owner));
    owner.setBulkSignupWarning(BulkSignups.exceededDailyLimit(owners, owner));
    owner.setCapacityWarning(CityCodes.countInCity(owners, owner) >= 40);
    owner.setPossibleDuplicateOf(
        PossibleDuplicates.matchId(owners, owner, ownerFieldsDto.getSharesHousehold()));
    this.clinicService.saveOwner(owner);
    IdempotencyKeys.remember(idempotencyKey, owner);
    OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
    headers.setLocation(UriComponentsBuilder.newInstance()
        .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
    return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
}

@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
