public static String uniqueFor(Owner owner, Collection<Owner> existing) {
    String base = CustomerCode.of(owner);
    Set<String> taken = existing.stream()
        .map(Owner::getCustomerCode).filter(Objects::nonNull).collect(Collectors.toSet());
    String code = base;
    for (int n = 2; taken.contains(code); n++) { code = base + "-" + n; }
    return code;
}
```

